def fib4(n: int) -> int:
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    elif n in (0, 1, 2):
        return 0 if n in (0, 1, 2) else 2
    elif n == 3:
        return 0

    seq = [0, 0, 2, 0, 4]
    for i in range(4, n + 1):
        next_value = seq[i - 1] + seq[i - 2] + seq[i - 3] + seq[i - 4]
        seq.append(next_value)

    return seq[n]
